config.description:
Feature-specific settings, generated from the backend serializers (contract sha256:a2c413a50107faf3ea47fa187089a930ac17d3d04893e24176f494a58470e982); a key outside the contract is dropped silently by the API. Features: AGE_ESTIMATION, AML, BANK_VERIFICATION, DATABASE_VALIDATION, DOCUMENT_AI, EMAIL_VERIFICATION, FACE_MATCH, GEOLOCATION, IP_ANALYSIS, KYB_DOCUMENTS, KYB_KEY_PEOPLE, KYB_REGISTRY, LIVENESS, NFC, OCR, PHONE_VERIFICATION, PROOF_OF_ADDRESS, QUESTIONNAIRE. Call didit_workflow_get_feature_config_schema for a feature's full key list, types and meaning. The keys whose value cannot be guessed:
  • AML.aml_field_sources: {"full_name"|"date_of_birth"|"nationality"|"document_number": {"source": "document_ai"|"questionnaire"|"expected_data", "key": "<docai field key>|<questionnaire node id>|expected_details.<expected_details field>|metadata.<key>"}} e.g. {"full_name":{"key":"razon_social","source":"document_ai"}}
  • BANK_VERIFICATION.bank_countries: {"<ISO3>": {"enabled": true|false, "institutions": ["<institution_id>", ...] | "all"}} e.g. {"ESP":{"enabled":true,"institutions":"all"}}
  • BANK_VERIFICATION.bank_field_sources: {"full_name"|"first_name"|"last_name"|"address": {"source": "document_ai"|"questionnaire"|"expected_data", "key": "<docai field key>|<questionnaire node id>|expected_details.<expected_details field>|metadata.<key>"}} e.g. {"full_name":{"key":"expected_details.first_name","source":"expected_data"}}
  • BANK_VERIFICATION.bank_scopes: {"ownership": true, "identifiers": true|false, "balances": true|false, "transactions": true|false, "income": true|false} e.g. {"ownership":true}
  • DATABASE_VALIDATION.database_validation_countries: {"<ISO3>": {"services": ["<service_id>", ...]}} e.g. {"BRA":{"services":["bra_cpf"]}}
  • DATABASE_VALIDATION.database_validation_field_sources: {"<db_validation_input_field>": {"source": "document_ai"|"questionnaire"|"expected_data", "key": "<docai field key>|<questionnaire node id>|expected_details.<expected_details field>|metadata.<key>"}} e.g. {"tax_id":{"key":"expected_details.identification_number","source":"expected_data"}}
  • GEOLOCATION.geolocation_geofencing_by_country: {"<ISO3>": {"allowed": true|false, "states"?: {"<ISO 3166-2 code>": {"allowed": true|false}} | null}} e.g. {"USA":{"allowed":true,"states":{"US-NJ":{"allowed":false}}}}
  • IP_ANALYSIS.ip_geofencing_by_country: {"<ISO3>": {"allowed": true|false, "states"?: {"<state_code>": {"allowed": true|false}} | null}} e.g. {"ESP":{"allowed":true,"states":null}}
  • KYB_DOCUMENTS.kyb_document_subtype_config: {"<KYB_DOCUMENT_GROUP|KYB_DOCUMENT_SUBTYPE>": {"enabled": true|false, "max_age_days": <0-3650>|-1|null}} e.g. {"LEGAL_PRESENCE":{"enabled":true,"max_age_days":90}}
  • KYB_DOCUMENTS.kyb_required_document_groups: ["<KYB_DOCUMENT_GROUP>", ...] e.g. ["LEGAL_PRESENCE"]
  • KYB_KEY_PEOPLE.kyb_key_people_company_fields: [{"key": "<field key>", "label": "<label>", "type": "text"|"number"|"date"|"phone"|"email", "required": true|false, "custom": true|false}] e.g. [{"custom":false,"key":"registration_number","label":"Registration number","required":true,"type":"text"}]
  • KYB_KEY_PEOPLE.kyb_key_people_person_fields: [{"key": "<field key>", "label": "<label>", "type": "text"|"number"|"date"|"phone"|"email", "required": true|false, "custom": true|false}] e.g. [{"custom":false,"key":"date_of_birth","label":"Date of birth","required":true,"type":"date"}]
  • KYB_KEY_PEOPLE.kyb_role_config: {"<role_key>": {"enabled"?: true|false, "require_kyc"?: true|false, "verification_workflow"?: "<workflow uuid>"|null, "allow_skip"?: true|false}} e.g. {"director":{"enabled":true,"require_kyc":false}}
  • KYB_REGISTRY.kyb_accepted_countries: ["<ISO2>", ...] e.g. ["ES","GB"]
  • KYB_REGISTRY.kyb_registry_countries_config: {"<ISO2>": {"enabled": true|false, "tier": "basic"|"shareholders"|"ubo"}} e.g. {"ES":{"enabled":true,"tier":"basic"}}
  • KYB_REGISTRY.kyb_registry_fields_config: {"<registry_field>": {"enabled"?: true|false, "required"?: true|false}} e.g. {"vat_number":{"enabled":true,"required":false}}
  • LIVENESS.race_map_similarity_thresholds: {"<race>": {"possible": 0-100, "high": 0-100}} e.g. {"asian":{"high":68,"possible":62}}
  • OCR.age_restrictions_by_country: {"<ISO3>": {"minimum_age": 1-120, "maximum_age": 1-120|null, "states"?: {"<STATE_CODE>": {"minimum_age": 1-120, "maximum_age": 1-120|null}}}} e.g. {"ESP":{"maximum_age":null,"minimum_age":18,"states":null}}
  • OCR.document_blur_fields_by_country: {"<ISO3>": ["<blur_field_name>", ...]} e.g. {"ESP":["Document Number"]}
  • OCR.documents_allowed: {"<ISO3>": {"<DOC_CODE>": {"enabled": 0|1, "sides"?: 1|2, "subtypes"?: ["<SUBTYPE_CODE>", ...]}}} e.g. {"ESP":{"P":{"enabled":1}}}
  • OCR.image_capture_methods_allowed: ["CAMERA_SCAN" | "UPLOAD", ...] e.g. ["CAMERA_SCAN"]
  • OCR.methods: {"<ISO3>": {"document": {"enabled": bool}, "id_lookup": {"enabled": bool, "source"?: "<source_id>"|null, "max_attempts": 1-5, "skip_liveness_and_face_match": bool, "on_partial_match": "fallback_to_document"|"decline", "on_no_match": "fallback_to_document"|"decline", "on_provider_error": "fallback_to_document"|"decline", "response_fields"?: ["<field_key>", ...]}, "wallet": {"enabled": bool, "providers": ["<wallet_id>", ...], "on_failure": "fallback_to_document"|"decline"}}} e.g. {"BRA":{"id_lookup":{"enabled":true,"source":"bra_cpf"}},"DNK":{"document":{"enabled":true},"wallet":{"enabled":true,"providers":["mitid"]}},"ZAF":{"document":{"enabled":true},"id_lookup":{"enabled":true,"max_attempts":2,"on_no_match":"fallback_to_document"}}}
  • OCR.ocr_id_verification_data_review_critical_fields: ["first_name" | "last_name" | "date_of_birth" | ...]
